import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function ProfilePage({ setIsProfileComplete }) {
  const [name, setName] = useState('');
  const [dob, setDob] = useState('');
  const [timelineValue, setTimelineValue] = useState('');
  const [timelineUnit, setTimelineUnit] = useState('months');
  const navigate = useNavigate();

  const handleSaveProfile = () => {
    setIsProfileComplete(true);
    navigate('/dashboard');
  };

  return (
    <div className="mx-auto max-w-4xl rounded-[2rem] bg-slate-900/80 p-8 shadow-2xl shadow-slate-950/30">
      <div className="grid gap-10 lg:grid-cols-[1.2fr_0.8fr]">
        <div className="space-y-4">
          <p className="text-sm uppercase tracking-[0.3em] text-cyan-300">Profile setup</p>
          <h2 className="text-3xl font-semibold text-white">Tell us about yourself to personalize your learning path.</h2>
          <p className="text-slate-400">Complete your profile in a few steps and let AI recommend the best roadmap for your goals.</p>
          <div className="space-y-4 rounded-3xl border border-slate-800 bg-slate-950/90 p-6">
            <label className="block text-sm font-medium text-slate-200">Full name</label>
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Jessica Parker"
              className="w-full rounded-3xl border border-slate-800 bg-slate-900 px-4 py-3 text-slate-100 outline-none transition focus:border-cyan-500"
            />
            <label className="block text-sm font-medium text-slate-200">Date of birth</label>
            <input
              type="date"
              value={dob}
              onChange={(e) => setDob(e.target.value)}
              className="w-full rounded-3xl border border-slate-800 bg-slate-900 px-4 py-3 text-slate-100 outline-none transition focus:border-cyan-500"
            />
            <label className="block text-sm font-medium text-slate-200">Target timeline</label>
            <div className="flex gap-4">
              <input
                type="number"
                value={timelineValue}
                onChange={(e) => setTimelineValue(e.target.value)}
                placeholder="6"
                className="flex-1 rounded-3xl border border-slate-800 bg-slate-900 px-4 py-3 text-slate-100 outline-none transition focus:border-cyan-500"
              />
              <select
                value={timelineUnit}
                onChange={(e) => setTimelineUnit(e.target.value)}
                className="rounded-3xl border border-slate-800 bg-slate-900 px-4 py-3 text-slate-100 outline-none transition focus:border-cyan-500"
              >
                <option value="months">Months</option>
                <option value="years">Years</option>
              </select>
            </div>
            <Button onClick={handleSaveProfile} className="w-full">Save profile</Button>
          </div>
        </div>
        <div className="rounded-[2rem] border border-slate-800 bg-slate-950/90 p-6">
          <h3 className="text-lg font-semibold text-white">Profile quick facts</h3>
          <div className="mt-6 space-y-4 text-sm text-slate-300">
            <div className="rounded-3xl bg-slate-900/80 p-5">
              <p className="text-slate-400">Personalized AI prompts</p>
              <p className="mt-2 text-white">Receive tailored learning activities based on your profile.</p>
            </div>
            <div className="rounded-3xl bg-slate-900/80 p-5">
              <p className="text-slate-400">Milestone timeline</p>
              <p className="mt-2 text-white">Plan study blocks and checkpoints across your preferred timeline.</p>
            </div>
            <div className="rounded-3xl bg-slate-900/80 p-5">
              <p className="text-slate-400">Goal-focused recommendations</p>
              <p className="mt-2 text-white">High-impact courses mapped to your career objective.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
